/* src/menu/marena_bridge.cpp - data holder / loader between the ARENA search pages and the AutoGen generators.
 * s_stArenaBridge keeps the three disc-loaded buffers (search-flag table, AutoGenName keyword list, PilotSearch pilot
 * data), the list of generated opponents (stAutoGenerateData[15]) and the Loading step. Init clears it, Loading reads
 * the three disc files in a 7-step async state machine (the page polls it until it returns 6), SearchBegin allocates /
 * clears the opponent list, Search runs AsmSearchInit + AsmSearch, SearchEnd sets the class flag of every named pilot
 * and copies its colours into the Asem data, the getters hand the pointers out, Cleanup frees the buffers.
 *
 * Original oddities kept: Init drops the buffers without freeing them; Cleanup never frees (or clears) pPilotData;
 * Loading's buffer size is size + 0x800 - size % 0x800 (a multiple of 0x800 still gets +0x800); SearchEnd stores the
 * class flag even when the Asem data pointer is 0.
 * g_aRankRangeTable is owned by this file's DWARF but defined (source port) in munit_arena_search.cpp; nothing here
 * reads it. The buffers are MMM (PS2) memory that interpreted code reads too: plain pointers. */
#include "acnb/port.h"
#include "acnb/sdk.h"

#ifdef ACNB_SOURCEPORT
struct stMArenaBridge s_stArenaBridge;   /* 0x1ef85e0 OLMENU (bss) */
#endif

/* CD file numbers of the three search files (flag table, keyword list, pilot data) */
enum { MAB_FILE_FLAG = 0x1074, MAB_FILE_KEYWORD = 0x1076, MAB_FILE_PILOT = 0x1078 };

int MArenaBridge_Search(struct stAsmSearchFlag *pFlagSearch)
{
    PS2_FRAME(0x20);
    if (AsmSearchInit() == 0) return 0;
    return AsmSearch(pFlagSearch) != 0;
}

void MArenaBridge_SearchEnd(void)
{
    PS2_FRAME(0x40);
    int i;
    for (i = 0; i < 15; i++) {
        struct stAutoGenerateData *p = &s_stArenaBridge.pAutoGenerateData[i];
        short id = p->id;
        if (id == -1) break;
        if (p->classPilot >= 100) {
            char *asem = MArenaAsemMng_GetAsemData();
            p = &s_stArenaBridge.pAutoGenerateData[i];   /* re-read after the call (original) */
            /* sllv: shift amount mod 32 */
            p->flagSearch.Class.Data = (char)(1u << ((p->classPilot - 100) & 31));
            if (asem != 0)
                ps2_memcpy(asem + id * 0x120 + 0x20, (char *)s_stArenaBridge.pAutoGenerateData + i * 0x120 + 0x50,
                           0xd0);
        }
    }
    s_stArenaBridge.numSearchData = (char)i;
}

void MArenaBridge_SearchBegin(void)
{
    PS2_FRAME(0x30);
    if (s_stArenaBridge.pAutoGenerateData) {
        DF_MMM_Free(0, s_stArenaBridge.pAutoGenerateData);
        s_stArenaBridge.pAutoGenerateData = 0;
    }
    s_stArenaBridge.pAutoGenerateData = (struct stAutoGenerateData *)DF_MMM_Alloc(0, 0x10e0);
    if (s_stArenaBridge.pAutoGenerateData) {
        for (int i = 0; i < 15; i++) {
            ps2_memset((char *)s_stArenaBridge.pAutoGenerateData + i * 0x120, 0, 0x120);
            s_stArenaBridge.pAutoGenerateData[i].id = -1;
        }
    }
}

char *MArenaBridge_GetAutoGenerateColor(int index)
{
    return (char *)s_stArenaBridge.pAutoGenerateData + index * 0x120 + 0x50;
}

char MArenaBridge_GetAutoGenerateDataNum(void)
{
    return s_stArenaBridge.numSearchData;
}

struct stAutoGenerateData *MArenaBridge_GetAutoGenerateData(void)
{
    return s_stArenaBridge.pAutoGenerateData;
}

char *MArenaBridge_GetPilotData(void)
{
    return s_stArenaBridge.pPilotData;
}

char *MArenaBridge_GetKeywordList(void)
{
    return s_stArenaBridge.pKeywordList;
}

char *MArenaBridge_GetFlagData(void)
{
    return s_stArenaBridge.pFlagDataHead;
}

void MArenaBridge_Cleanup(void)
{
    PS2_FRAME(0x10);
    if (s_stArenaBridge.pKeywordList) {
        DF_MMM_Free(0, s_stArenaBridge.pKeywordList);
        s_stArenaBridge.pKeywordList = 0;
    }
    if (s_stArenaBridge.pFlagDataHead) {
        DF_MMM_Free(0, s_stArenaBridge.pFlagDataHead);
        s_stArenaBridge.pFlagDataHead = 0;
    }
    if (s_stArenaBridge.pAutoGenerateData) {
        DF_MMM_Free(0, s_stArenaBridge.pAutoGenerateData);
        s_stArenaBridge.pAutoGenerateData = 0;
    }
    /* (sic) pPilotData is never freed */
}

/* size rounded up to the next 0x800 block, +0x800 when already aligned (C signed remainder) */
static inline int mab_buf_size(int size)
{
    return size + (0x800 - size % 0x800);
}

/* allocate a buffer for disc file `id` and start its async read; 0 = allocation failed */
static inline char *mab_load_start(int id, char **ppBuf)
{
    int size = Cdvd_GetSizeByte(id);
    *ppBuf = (char *)DF_MMM_Alloc(0, mab_buf_size(size));
    char *buf = *ppBuf;   /* re-read from the static (original) */
    if (!buf) return 0;
    Cdvd_ReadLsnBlind((unsigned int)id, buf, 0, 0);
    return buf;
}

char MArenaBridge_Loading(void)
{
    PS2_FRAME(0x10);
    switch (s_stArenaBridge.step) {   /* signed byte: negative steps take the default */
    case 0:
        if (!mab_load_start(MAB_FILE_FLAG, &s_stArenaBridge.pFlagDataHead)) return -1;
        s_stArenaBridge.step = 1;
        break;
    case 1:
        if (File_IsAsyncBusy()) break;
        s_stArenaBridge.step = 2;
        break;
    case 2:
        if (!mab_load_start(MAB_FILE_KEYWORD, &s_stArenaBridge.pKeywordList)) return -1;
        s_stArenaBridge.step = 3;
        break;
    case 3:
        if (File_IsAsyncBusy()) break;
        s_stArenaBridge.step = 4;
        break;
    case 4:
        if (!mab_load_start(MAB_FILE_PILOT, &s_stArenaBridge.pPilotData)) return -1;
        s_stArenaBridge.step = 5;
        break;
    case 5:
        if (File_IsAsyncBusy()) break;
        s_stArenaBridge.step = 6;
        break;
    default:   /* 6: loaded */
        break;
    }
    return s_stArenaBridge.step;
}

int MArenaBridge_Init(void)
{
    PS2_FRAME(0x10);
    ps2_memset(&s_stArenaBridge, 0, 0x14);
    return 1;
}
